for file in sorted(Path('scripts/legacy-articles').glob('*.html')):
 path='/articles/'+file.stem+'/'
 if path in pages: continue
 source=file.read_text()
 h=re.search(r'<h1[^>]*>(.*?)</h1>',source,re.S)
 body=re.search(r'<article class="article-content">(.*?)</article>',source,re.S)
 if not h or not body: continue
 title=re.sub('<[^>]+>','',h[1]).strip()
 content=body[1].replace('https://www.geekservicesny.com','https://geekservicesny.com').replace('../../index.html#contact','/contact/').replace('../index.html#contact','/contact/').replace('../../index.html','/').replace('../../founder.html','/founder/')
 content=re.sub(r'href="(?:\.\./)+articles/', 'href="/articles/',content)
 desc='Practical guidance from Geek Services on '+file.stem.replace('-',' ')+'.'
 add(path,title+' | Geek Services',desc,title,content+section('Apply this in Albany',link('/services/business-technology/','Explore business technology services')+p(link('/locations/albany/','Technology support in Albany'))+p(link('/contact/','Request a consultation'))),'Articles / Practical technology','Article')
 article_items.append((path,title,desc))
